// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 1);
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertEq(address(c).balance, amount);

        // owner is this contract (msg.sender at deployment)
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
